import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
conv3d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#define TILE_D 16
#define TILE_H 16
#define TILE_W 8
#define MAX_OC_TILE 4
__global__ void conv3d_kxk1_tiled_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int batch_size,
    const int in_channels,
    const int out_channels,
    const int D_in, const int H_in, const int W_in,
    const int D_out, const int H_out, const int W_out,
    const int kD, const int kH, const int kW,
    const int stride,
    const int padding,
    const int dilation,
    const int groups,
    const int in_channels_per_group,
    const int out_channels_per_group,
    const bool has_bias,
    const int SH_D,
    const int SH_H,
    const int W_tiles,
    const int oc_tile,
    const int num_oc_tiles)
{
    extern __shared__ float smem[];
    int wsize = in_channels_per_group * kD * kH;
    float* s_weight = smem; // oc_tile * in_channels_per_group * kD * kH
    float* s_input = smem + (long)oc_tile * wsize; // TILE_W * in_channels_per_group * SH_D * SH_H
    int bz = blockIdx.z;
    int ow_tile = bz % W_tiles; bz /= W_tiles;
    int oc_tile_idx = bz % num_oc_tiles; bz /= num_oc_tiles;
    int n = bz;
    int oc0 = oc_tile_idx * oc_tile;
    int g = oc0 / out_channels_per_group;
    int ic_start = g * in_channels_per_group;
    int od0 = blockIdx.x * TILE_D;
    int oh0 = blockIdx.y * TILE_H;
    int ow0 = ow_tile * TILE_W;
    int tx = threadIdx.x; // local od
    int ty = threadIdx.y; // local oh
    int od = od0 + tx;
    int oh = oh0 + ty;
    int tid = ty * TILE_D + tx;
    int nthreads = TILE_D * TILE_H;
    // Cooperative load of weights for this tile of output channels into shared memory
    // (loading a tile of oc_tile output channels' weights at once lets us reuse the
    //  same staged input tile across multiple output channels, avoiding redundant
    //  global memory reloads of the input that previously happened once per oc)
    int wtotal = oc_tile * wsize;
    for (int i = tid; i < wtotal; i += nthreads) {
        int oc_local = i / wsize;
        int rem0 = i % wsize;
        int icl = rem0 / (kD * kH);
        int rem = rem0 % (kD * kH);
        int kd = rem / kH;
        int kh = rem % kH;
        int oc = oc0 + oc_local;
        long widx = ((((long)oc * in_channels_per_group + icl) * kD + kd) * kH + kh) * kW + 0;
        s_weight[i] = weight[widx];
    }
    // kW is 1, so only a single depth (W) index needs to be checked, per local ow within the tile
    int id_min = od0 * stride - padding;
    int ih_min = oh0 * stride - padding;
    long in_size = (long)in_channels_per_group * SH_D * SH_H;
    // Load input slabs for all local ow's in this tile into shared memory
    // (shared across all oc's processed by this block - key reuse optimization)
    {
        bool base_valid_range = (stride == 1) && (ow0 + TILE_W <= W_out);
        int iw_base = ow0 * stride - padding;
        base_valid_range = base_valid_range && (iw_base >= 0) && (iw_base + (TILE_W - 1) < W_in);
        for (long i = tid; i < in_size; i += nthreads) {
            int icl = (int)(i / (SH_D * SH_H));
            int rem = (int)(i % (SH_D * SH_H));
            int sd = rem / SH_H;
            int sh = rem % SH_H;
            int id = id_min + sd;
            int ih = ih_min + sh;
            bool id_valid = (id >= 0 && id < D_in);
            bool ih_valid = (ih >= 0 && ih < H_in);
            if (base_valid_range && id_valid && ih_valid) {
                int ic = ic_start + icl;
                long input_base = (((long)n * in_channels + ic) * D_in + id) * H_in * W_in
                                  + (long)ih * W_in + iw_base;
                if ((input_base & 3L) == 0) {
                    #pragma unroll
                    for (int q = 0; q < TILE_W / 4; q++) {
                        float4 v4 = *reinterpret_cast<const float4*>(input + input_base + (long)q * 4);
                        s_input[(long)(q * 4 + 0) * in_size + i] = v4.x;
                        s_input[(long)(q * 4 + 1) * in_size + i] = v4.y;
                        s_input[(long)(q * 4 + 2) * in_size + i] = v4.z;
                        s_input[(long)(q * 4 + 3) * in_size + i] = v4.w;
                    }
                } else {
                    #pragma unroll
                    for (int w = 0; w < TILE_W; w++) {
                        s_input[(long)w * in_size + i] = input[input_base + w];
                    }
                }
            } else {
                #pragma unroll
                for (int w = 0; w < TILE_W; w++) {
                    int ow = ow0 + w;
                    bool ow_valid_col = (ow < W_out);
                    int iw = ow * stride - padding;
                    bool iw_valid = ow_valid_col && (iw >= 0 && iw < W_in);
                    float val = 0.0f;
                    if (iw_valid && id_valid && ih_valid) {
                        int ic = ic_start + icl;
                        long input_idx = (((long)n * in_channels + ic) * D_in + id) * H_in * W_in
                                          + (long)ih * W_in + iw;
                        val = input[input_idx];
                    }
                    s_input[(long)w * in_size + i] = val;
                }
            }
        }
    }
    __syncthreads();
    if (od < D_out && oh < H_out) {
        float accs[MAX_OC_TILE][TILE_W];
        #pragma unroll
        for (int oc_local = 0; oc_local < MAX_OC_TILE; oc_local++) {
            #pragma unroll
            for (int w = 0; w < TILE_W; w++) {
                accs[oc_local][w] = 0.0f;
            }
        }
        #pragma unroll
        for (int w = 0; w < TILE_W; w++) {
            int ow = ow0 + w;
            if (ow < W_out) {
                const float* s_in_w = s_input + (long)w * in_size;
                for (int icl = 0; icl < in_channels_per_group; icl++) {
                    const float* s_in_c = s_in_w + (long)icl * SH_D * SH_H;
                    for (int kd = 0; kd < kD; kd++) {
                        int sd = tx * stride + kd * dilation;
                        const float* s_in_row = s_in_c + (long)sd * SH_H;
                        for (int kh = 0; kh < kH; kh++) {
                            int sh = ty * stride + kh * dilation;
                            float in_val = s_in_row[sh];
                            #pragma unroll
                            for (int oc_local = 0; oc_local < oc_tile; oc_local++) {
                                const float* s_w_oc = s_weight + (long)oc_local * wsize;
                                float w_val = s_w_oc[(icl * kD + kd) * kH + kh];
                                accs[oc_local][w] += in_val * w_val;
                            }
                        }
                    }
                }
                if (has_bias) {
                    #pragma unroll
                    for (int oc_local = 0; oc_local < oc_tile; oc_local++) {
                        accs[oc_local][w] += bias[oc0 + oc_local];
                    }
                }
            }
        }
        for (int oc_local = 0; oc_local < oc_tile; oc_local++) {
            int oc = oc0 + oc_local;
            long output_base = (((long)n * out_channels + oc) * D_out + od) * H_out * W_out
                               + (long)oh * W_out + ow0;
            if (ow0 + TILE_W <= W_out && ((output_base & 3L) == 0)) {
                #pragma unroll
                for (int q = 0; q < TILE_W / 4; q++) {
                    float4 out4 = make_float4(accs[oc_local][q * 4 + 0], accs[oc_local][q * 4 + 1],
                                               accs[oc_local][q * 4 + 2], accs[oc_local][q * 4 + 3]);
                    *reinterpret_cast<float4*>(output + output_base + (long)q * 4) = out4;
                }
            } else {
                #pragma unroll
                for (int w = 0; w < TILE_W; w++) {
                    int ow = ow0 + w;
                    if (ow < W_out) {
                        output[output_base + w] = accs[oc_local][w];
                    }
                }
            }
        }
    }
}
torch::Tensor conv3d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    int groups,
    bool has_bias)
{
    input = input.contiguous();
    weight = weight.contiguous();
    if (has_bias) {
        bias = bias.contiguous();
    }
    const int batch_size = input.size(0);
    const int in_channels = input.size(1);
    const int D_in = input.size(2);
    const int H_in = input.size(3);
    const int W_in = input.size(4);
    const int out_channels = weight.size(0);
    const int in_channels_per_group = weight.size(1);
    const int kD = weight.size(2);
    const int kH = weight.size(3);
    const int kW = weight.size(4);
    const int out_channels_per_group = out_channels / groups;
    const int D_out = (D_in + 2 * padding - dilation * (kD - 1) - 1) / stride + 1;
    const int H_out = (H_in + 2 * padding - dilation * (kH - 1) - 1) / stride + 1;
    const int W_out = (W_in + 2 * padding - dilation * (kW - 1) - 1) / stride + 1;
    auto output = torch::empty({batch_size, out_channels, D_out, H_out, W_out}, input.options());
    const int SH_D = (TILE_D - 1) * stride + (kD - 1) * dilation + 1;
    const int SH_H = (TILE_H - 1) * stride + (kH - 1) * dilation + 1;
    const int W_tiles = (W_out + TILE_W - 1) / TILE_W;
    int oc_tile = 1;
    if (out_channels_per_group % 4 == 0) {
        oc_tile = 4;
    } else if (out_channels_per_group % 2 == 0) {
        oc_tile = 2;
    } else {
        oc_tile = 1;
    }
    if (oc_tile > MAX_OC_TILE) oc_tile = MAX_OC_TILE;
    const int num_oc_tiles = out_channels / oc_tile;
    dim3 block(TILE_D, TILE_H);
    dim3 grid(
        (D_out + TILE_D - 1) / TILE_D,
        (H_out + TILE_H - 1) / TILE_H,
        (unsigned int)((long)batch_size * num_oc_tiles * W_tiles)
    );
    size_t shmem_bytes = (size_t)((long)oc_tile * in_channels_per_group * kD * kH + (long)TILE_W * in_channels_per_group * SH_D * SH_H) * sizeof(float);
    const float* bias_ptr = has_bias ? bias.data_ptr<float>() : nullptr;
    conv3d_kxk1_tiled_kernel<<<grid, block, shmem_bytes>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        D_in, H_in, W_in,
        D_out, H_out, W_out,
        kD, kH, kW,
        stride,
        padding,
        dilation,
        groups,
        in_channels_per_group,
        out_channels_per_group,
        has_bias,
        SH_D,
        SH_H,
        W_tiles,
        oc_tile,
        num_oc_tiles);
    return output;
}
